#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2Logic.Resources;
using UnityEngine;

namespace MVZ2.Sprites
{
    public class SpriteDatabase : ISpriteProvider
    {
        public void Register(SpriteLookupKey key, Sprite sprite)
        {
            sprites[key] = sprite;
            reversedSpriteDict[sprite] = key;
        }
        
        public void Clear()
        {
            sprites.Clear();
            reversedSpriteDict.Clear();
        }
        public SpriteLookupKey? GetKey(Sprite sprite)
        {
            if (!sprite)
                return null;
            if (reversedSpriteDict.TryGetValue(sprite, out var sprRef))
            {
                return sprRef;
            }
            return null;
        }
        public bool TryGet(SpriteLookupKey key, out Sprite? sprite)
        {
            return sprites.TryGetValue(key, out sprite);
        }
        public int Priority { get; set; }
        private readonly Dictionary<SpriteLookupKey, Sprite> sprites = new();
        private readonly Dictionary<Sprite, SpriteLookupKey> reversedSpriteDict = new Dictionary<Sprite, SpriteLookupKey>();
    }
}
